"""Generate offline social observatory from the exported sample trace."""
from pathlib import Path
import json, math, argparse

def main():
    ap=argparse.ArgumentParser()
    ap.add_argument('--json', default='results/social_agents_25/demo_observatory.json')
    ap.add_argument('--output',default='results/social_agents_25/social_observatory.html')
    opts=ap.parse_args()
    data=json.loads(Path(opts.json).read_text())
    payload=json.dumps(data,separators=(',',':')).replace('</','<\\/')
    html=r'''<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"/><meta name="viewport" content="width=device-width,initial-scale=1"/>
<title>Founders-CIV · Social Observatory Pilot</title><style>
:root {font-family:Inter,system-ui,-apple-system,sans-serif;color:#eaf3ff;background:#08111c}
*{box-sizing:border-box} body{margin:0;background:linear-gradient(120deg,#08111c,#10253b)} header{padding:22px 28px;border-bottom:1px solid #294057}
small,.muted{color:#9eb5c7} h1{font-size:25px;margin:0 0 7px;letter-spacing:-.035em}h2{font-size:15px;margin:2px 0 12px}
main{display:grid;grid-template-columns:minmax(410px,1fr) 335px;gap:16px;padding:16px;max-width:1450px;margin:0 auto}
.panel{background:#0e2132e8;border:1px solid #28465a;border-radius:14px;padding:16px;box-shadow:0 18px 40px #0002}
#network{width:100%;height:auto;max-height:70vh;background:#0a1b2a;border-radius:10px}
.controls{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-bottom:10px}
input[type=range]{width:200px}select{background:#172e41;color:#eaf3ff;border:1px solid #446178;border-radius:7px;padding:8px}
.statbar{display:flex;gap:12px;flex-wrap:wrap;margin:12px 0}.stat{background:#1a3547;padding:10px;border-radius:9px;min-width:135px}
.stat strong{display:block;font-size:19px}.stat span{font-size:11px;color:#b2c5d1}
#detail p{margin:7px 0;font-size:13px}#events{max-height:280px;overflow:auto}
.event{font-size:12px;border-bottom:1px solid #294357;padding:7px 0;line-height:1.4}
.swatch{display:inline-block;width:10px;height:10px;border-radius:50%;margin-right:7px;vertical-align:middle}
.legend{display:flex;gap:10px;flex-wrap:wrap;margin:5px 0 10px;font-size:11px;color:#b9d0de}
button{background:#184c66;border:1px solid #43839a;border-radius:7px;color:#fff;padding:8px;cursor:pointer}
.note{color:#93afbf;font-size:11px;line-height:1.5}
@media(max-width:850px){main{grid-template-columns:1fr}.panel{min-width:0} header{padding:16px}main{padding:8px}#network{max-height:none}}
</style></head><body>
<header><h1>FOUNDERS / CIV — Social Observatory</h1><small>Experimental SOCIAL-021 · 100 Founders · 8 provisional squads + 4 officers · seed <span id="seed"></span></small></header>
<main><section><div class="panel">
<div class="controls"><label for="tick">Cycle: <b id="tickVal">1</b></label><input type="range" id="tick" min="1" max="30" value="1"/>
<label><input id="partners" type="checkbox" checked/> Partner links</label><label><input id="factions" type="checkbox" checked/> Faction links</label></div>
<div class="legend"><span><i class="swatch" style="background:#67c7e6"></i>Founder: unaligned</span><span><i class="swatch" style="background:#faaf6b"></i>Faction member</span><span><i class="swatch" style="background:#dbadf0"></i>Officer</span></div>
<svg id="network" viewBox="0 0 800 695" role="img" aria-label="Social network diagram, not geographic coordinates"></svg>
<div class="statbar" id="statbar"></div><div class="note">Schematic squad-centered layout, not coordinates in the Sea. Partner connections are initial historical ties; factions form from proposals and endorsements. Click any Founder for details.</div>
</div><div class="panel" style="margin-top:16px"><h2>Selected cycle events</h2><div id="events"></div></div></section>
<aside><div class="panel"><h2>Founder Inspector</h2><div class="controls"><select id="actor"></select></div><div id="detail"></div></div>
<div class="panel" style="margin-top:16px"><h2>Current factions</h2><div id="factionlist"></div></div>
<div class="panel" style="margin-top:16px"><h2>Evidence status</h2><p class="note">This interface reads actual sample events and snapshots generated by the SOCIAL-021 experimental scheduler. It is not connected to the main ecological simulation and does not establish psychological realism. The model's trust and learning coefficients are provisional.</p></div>
</aside></main><script>
const DATA = __DATA__;
const SVG='http://www.w3.org/2000/svg';
const $=s=>document.querySelector(s);const byId={};
const positions={};
const squads=[...Array(8)].map((_,i)=>`SQ${String(i+1).padStart(2,'0')}`);
for(let j=0;j<8;j++){
  const a=-Math.PI/2+2*Math.PI*j/8, cx=400+260*Math.cos(a),cy=332+245*Math.sin(a);
  for(let k=0;k<12;k++){const n=j*12+k+1, v=2*Math.PI*k/12;
    positions[`F${String(n).padStart(3,'0')}`]={x:cx+56*Math.cos(v),y:cy+49*Math.sin(v)};}
}
for(let k=0;k<4;k++){let a=2*Math.PI*k/4; positions[`F${String(97+k).padStart(3,'0')}`]={x:400+35*Math.cos(a),y:332+35*Math.sin(a)}}
const state={selected:'F001'};
$('#seed').textContent=DATA.seed;
$('#tick').max=DATA.observations.length;
for(let i=1;i<=100;i++){let id=`F${String(i).padStart(3,'0')}`,o=document.createElement('option');o.value=id;o.textContent=id;$('#actor').appendChild(o)}
function el(tag,attrs={}){let e=document.createElementNS(SVG,tag);for(let [k,v] of Object.entries(attrs))e.setAttribute(k,v);return e}
function render(){
 const snap=DATA.observations[Number($('#tick').value)-1];if(!snap)return;
 $('#tickVal').textContent=snap.tick;
 const actors=snap.actors,lookup=Object.fromEntries(actors.map(a=>[a.id,a]));let graph=$('#network');graph.replaceChildren();
 for(let j=0;j<8;j++){let a=-Math.PI/2+j*Math.PI/4,x=400+260*Math.cos(a),y=332+245*Math.sin(a);
  let txt=el('text',{x,y:y-74,'text-anchor':'middle',fill:'#8fb2c4','font-size':13});txt.textContent=squads[j];graph.appendChild(txt)}
 let officerTitle=el('text',{x:400,y:263,'text-anchor':'middle',fill:'#d1a1ee','font-size':13});officerTitle.textContent='OFFICERS';graph.appendChild(officerTitle)
 if($('#partners').checked){for(let a of actors){if(a.id>a.partner)continue;let p=positions[a.id],q=positions[a.partner];graph.appendChild(el('line',{x1:p.x,y1:p.y,x2:q.x,y2:q.y,stroke:'#537c98','stroke-opacity':.23,'stroke-width':1.2}))}}
 if($('#factions').checked){for(let fac of snap.factions){let p=positions[fac.founder];for(let b of fac.members){if(b===fac.founder)continue;let q=positions[b];graph.appendChild(el('line',{x1:p.x,y1:p.y,x2:q.x,y2:q.y,stroke:'#ffae67','stroke-opacity':.65,'stroke-width':1.5,'stroke-dasharray':'4,3'}))}}}
 for(let a of actors){let pos=positions[a.id],selected=a.id===state.selected,
  color=a.faction?'#faaf6b':a.officer?'#dbadf0':'#67c7e6';
  let circle=el('circle',{cx:pos.x,cy:pos.y,r:selected?11:6.5,fill:color,stroke:selected?'#fff':'#0e283a','stroke-width':selected?2.8:1.5,style:'cursor:pointer'});
  circle.addEventListener('click',()=>{state.selected=a.id;$('#actor').value=a.id;render()});
  let title=el('title');title.textContent=`${a.id} · ${a.squad} · ${a.goal}${a.faction?' · '+a.faction:''}`;circle.appendChild(title);graph.appendChild(circle)
 }
 const sel=lookup[state.selected];if(sel){
 $('#detail').innerHTML=`<p><b>${sel.id}</b> · ${sel.squad}${sel.officer?' · Officer':''}</p><p><b>Goal:</b> ${sel.goal}</p><p><b>Ambition:</b> ${sel.ambition}</p><p><b>Starting specialty:</b> ${sel.specialty}</p><p><b>Location:</b> ${sel.location}</p><p><b>Partner:</b> ${sel.partner}</p><p><b>Trust toward partner:</b> ${sel.partner_trust}</p><p><b>Faction:</b> ${sel.faction||'Unaffiliated'}</p><p><b>Practiced skills:</b><br>${Object.entries(sel.skills).map(([k,v])=>`${k}: ${v}`).join(' · ')}</p><p><b>Encountered knowledge:</b><br>${Object.entries(sel.knowledge).map(([k,v])=>`${k}: ${v}`).join(' · ')||'None recorded'}</p>`
 }
 let f=snap.factions;
 $('#factionlist').innerHTML=f.length?f.map(o=>`<p style="font-size:12px"><b>${o.id}</b>: ${o.agenda} · ${o.members.length} members · founded by ${o.founder}</p>`).join(''):'<p class="note">No faction has reached the three-supporter requirement yet.</p>';
 $('#statbar').innerHTML=`<div class="stat"><strong>${f.length}</strong><span>Formed factions</span></div><div class="stat"><strong>${new Set(f.flatMap(x=>x.members)).size}</strong><span>Members of factions</span></div><div class="stat"><strong>${actors.filter(a=>Object.keys(a.knowledge).length).length}</strong><span>Exposed to knowledge</span></div><div class="stat"><strong>${snap.actions.teach||0}</strong><span>Cumulative lessons</span></div>`;
 const ev=DATA.events.filter(e=>e.tick===snap.tick && (e.actor===state.selected || e.target===state.selected));
 $('#events').innerHTML=ev.length?ev.slice(0,30).map(e=>`<div class="event"><b>${e.action}</b> · ${e.actor} ${e.target?'→ '+e.target:''}<br><span class="muted">${e.event_id}${e.transaction_id?' · TX'+e.transaction_id:''}${e.claim?' · '+e.claim:''}${e.outcome?' · '+e.outcome:''}</span></div>`).join(''):'<p class="note">No matching events for this Founder in this cycle.</p>';
}
for(let id of ['tick','partners','factions'])$('#'+id).addEventListener('input',render);
$('#actor').addEventListener('change',e=>{state.selected=e.target.value;render()});render();
</script></body></html>'''
    html=html.replace('__DATA__',payload)
    target=Path(opts.output);target.parent.mkdir(parents=True,exist_ok=True)
    target.write_text(html,encoding='utf8')
    print(target,'bytes',target.stat().st_size)
if __name__=='__main__':main()
